/**
 * Theme registry + balance engine for autonomous blog production.
 * Agents may append new themes here when creation criteria are met.
 */

import type { Category } from "@/types/post";
import { NOVEL_THEMES } from "./novel-themes.ts";

export type ThemeLane =
  | "ai-infrastructure"
  | "global-systems"
  | "macro-economics"
  | "geopolitics-governance"
  | "markets-finance"
  | "industrial-adoption";

export type PipelineCandidate = {
  title: string;
  coreQuestion: string;
  primarySources: string[];
  headlineStatHint: string;
  overlapNotes: string;
  priority: "high" | "medium";
};

export type ThemeDefinition = {
  id: string;
  label: string;
  lane: ThemeLane;
  category: Category;
  metaQuestion: string;
  visualLane: string;
  /** Target % of rolling window (all active themes should sum ~100) */
  targetSharePct: number;
  /** Hard cap % in rolling window ??? block selection above this */
  maxSharePct: number;
  /** Max consecutive posts with this theme id */
  maxConsecutive: number;
  /** After this many lifetime posts, do not mint sequels ??? unused named candidates may still claim */
  maxLifetimePosts?: number;
  status: "active" | "proposed";
  candidates: PipelineCandidate[];
};

export const BALANCE_CONFIG = {
  /** Posts used for representation math */
  rollingWindow: 24,
  /** Max posts in a row from the same lane */
  maxConsecutivePerLane: 1,
  /** If a lane exceeds this % in rolling window, next post MUST be another lane */
  laneHardCapPct: 28,
  /** If a lane is below this % and has active themes, prefer it */
  laneStarvationPct: 6,
  /** Default lifetime posts before a theme is treated as covered (no sequels) */
  defaultMaxLifetimePosts: 2,
  /** AI infrastructure sequels are banned after a single shipped post */
  aiInfrastructureLifetimeCap: 1,
  /** Min rubric score to justify creating a new theme */
  newThemeMinRubric: 22,
} as const;

export const LANE_LABELS: Record<ThemeLane, string> = {
  "ai-infrastructure": "AI infrastructure",
  "global-systems": "Global Systems",
  "macro-economics": "Macro economics",
  "geopolitics-governance": "Geopolitics & governance",
  "markets-finance": "Markets & finance",
  "industrial-adoption": "Industrial adoption",
};

/** Default category per lane (override per theme if needed) */
export const LANE_DEFAULT_CATEGORY: Record<ThemeLane, Category> = {
  "ai-infrastructure": "Technology",
  "global-systems": "Global Systems",
  "macro-economics": "Economics",
  "geopolitics-governance": "Politics",
  "markets-finance": "Finance",
  "industrial-adoption": "Industry",
};

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.",
  "tool": {
    "tool": "GenerateImage",
    "description": "Generate an image file from a text description.\n\nSTRICT INVOCATION RULES (must follow):\n- Only use this tool when the user explicitly asks for an image. Do not generate images \"just to be helpful\".\n- Do not use this tool for data heavy visualizations such as charts, plots, tables.\n\nGeneral guidelines:\n- Provide a concrete description first: subject(s), layout, style, colors, text (if any), and constraints.\n- If the user requests an aspect ratio, set `aspect_ratio` to one of \"1:1\", \"4:3\", \"3:4\", \"16:9\", or \"9:16\".\n- If the user provides reference images, include them in `reference_image_paths`.\n- Do not repeat generated images as Markdown in your response; the client displays tool-generated images automatically.\n\nExamples that should call this tool:\n- user: \"Generate an app icon for a note-taking app, minimal flat vector style.\" (explicitly requests an image asset)\n- user: \"Make a UI mockup of a settings screen with a dark mode toggle.\" (explicitly requests a UI mockup)\n- user: \"Generate an asset of a game character with a sword.\" (explicitly requests a visual asset)\n\nExamples that should not call this tool:\n- user: \"Create a plan to refactor this module.\" (planning request; respond in text or mermaid diagram)\n- user: \"Generate a chart of sales and revenue using data.csv.\" (data visualization; generate via code)",
    "inputSchema": {
      "type": "object",
      "properties": {
        "description": {
          "type": "string",
          "description": "A detailed description of the image."
        },
        "filename": {
          "type": "string",
          "description": "Optional filename for the generated image (e.g., 'diagram.png'). Do not include a directory path - the tool automatically handles where to save and how to display the image. If not provided, a timestamped filename will be generated."
        },
        "reference_image_paths": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Optional array of file paths to reference images as additional inputs."
        },
        "aspect_ratio": {
          "type": "string",
          "enum": [
            "1:1",
            "4:3",
            "3:4",
            "16:9",
            "9:16"
          ],
          "description": "Optional aspect ratio for the generated image. Supported values are \"1:1\", \"4:3\", \"3:4\", \"16:9\", and \"9:16\"."
        }
      },
      "required": [
        "description"
      ]
    }
  }
}

